// hid_prank_unicode.ino — ESP32-S3 (USB HID)
// GPIO4: Win+R -> cmd -> color 2 -> dir /s -> F11
// Все буквы — через Alt+Numpad (код ASCII), раскладка не важна
#include "Keyboard.h"

const int BTN = 4;

// Сырые HID-usage коды нумпада (константы KEY_KP_* в библиотеке нет,
// поэтому задаём вручную; в press() они идут как usage+136)
const uint8_t KP0 = 0x62 + 136;
const uint8_t KP1 = 0x59 + 136;
const uint8_t KP2 = 0x5A + 136;
const uint8_t KP3 = 0x5B + 136;
const uint8_t KP4 = 0x5C + 136;
const uint8_t KP5 = 0x5D + 136;
const uint8_t KP6 = 0x5E + 136;
const uint8_t KP7 = 0x5F + 136;
const uint8_t KP8 = 0x60 + 136;
const uint8_t KP9 = 0x61 + 136;
const uint8_t KP_DIGITS[10] = {KP0, KP1, KP2, KP3, KP4, KP5, KP6, KP7, KP8, KP9};

struct Btn {
  uint8_t pin;
  bool lastReading = false, state = false;
  unsigned long lastChange = 0;
};
Btn btn{BTN};

bool checkPress(Btn &b) {
  bool reading = (digitalRead(b.pin) == LOW);
  if (reading != b.lastReading) { b.lastChange = millis(); b.lastReading = reading; }
  if (millis() - b.lastChange > 50 && reading != b.state) {
    b.state = reading;
    if (b.state) return true;
  }
  return false;
}

void tapNumLock() {
  Keyboard.press(KEY_NUM_LOCK);
  Keyboard.release(KEY_NUM_LOCK);
  delay(60);
}

// Одна цифра на нумпаде
void kpDigit(int d) {
  Keyboard.press(KP_DIGITS[d]);
  Keyboard.release(KP_DIGITS[d]);
  delay(20);
}

// Символ через Alt+0NNN — ANSI-код, работает при любой раскладке
void typeAltChar(char c) {
  int code = (int)c;
  Keyboard.press(KEY_LEFT_ALT);
  delay(40);
  kpDigit(0);                       // ведущий ноль = таблица ANSI (латиница гарантированно)
  String s = String(code);
  while (s.length() < 3) s = "0" + s;
  for (unsigned int i = 0; i < s.length(); i++) kpDigit(s[i] - '0');
  delay(40);
  Keyboard.release(KEY_LEFT_ALT);
  delay(40);
}

void typeAltString(const char* s) {
  for (unsigned int i = 0; i < strlen(s); i++) typeAltChar(s[i]);
}

void pressEnter() {
  Keyboard.press(KEY_RETURN);
  Keyboard.release(KEY_RETURN);
  delay(200);
}

void runPrank() {
  tapNumLock();                     // включить нумпад для Alt-кодов

  // Win+R -> cmd
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(80);
  Keyboard.releaseAll();
  delay(500);
  typeAltString("cmd");
  pressEnter();
  delay(800);                       // ждём окно консоли

  typeAltString("color 2");
  pressEnter();
  delay(200);

  typeAltString("dir /s");
  pressEnter();

  delay(300);
  Keyboard.press(KEY_F11);
  Keyboard.release(KEY_F11);
}

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  Keyboard.begin();
}

void loop() {
  if (checkPress(btn)) runPrank();
}
